package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import java.io.File;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** CI-only real native plan/storage/receiver policy with fake clock, scheduler and notification output. */
public class TravelPlanFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private TravelActivity activity;
    private UiObject2 object(String description)throws Exception{UiObject2 result=device.wait(Until.findObject(By.desc(description)),2000);if(result==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));result=device.wait(Until.findObject(By.desc(description)),5000);}assertNotNull(description,result);return result;}
    private void clickDescription(String description)throws Exception{object(description).click();device.waitForIdle();}
    private void click(String label)throws Exception{UiObject2 result=device.wait(Until.findObject(By.text(label)),1500);if(result==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(label));result=device.wait(Until.findObject(By.text(label)),5000);}assertNotNull(label,result);result.click();device.waitForIdle();}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(TravelActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,TravelActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(TravelActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull("A fresh travel window must open",activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Save travel settings")),5000));}
    private void capture(String name)throws Exception{long deadline=SystemClock.elapsedRealtime()+5000;CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<deadline){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("A focused hardware travel window is required",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"travel-"+name+".png")));}
    private void destroyed(Activity target){long deadline=SystemClock.elapsedRealtime()+5000;boolean[] done={false};while(!done[0]&&SystemClock.elapsedRealtime()<deadline){i.runOnMainSync(()->done[0]=target.isDestroyed());if(!done[0])SystemClock.sleep(50);}assertTrue("Saved travel window must close",done[0]);}
    private void recreate(String expected)throws Exception{Activity prior=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(TravelActivity.class.getName(),null,false);try{i.runOnMainSync(prior::recreate);activity=(TravelActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text(expected)),5000));}
    @Test public void savedZonesDstRemindersDeliveryCancelAndFailureAreRealExceptInjectedOutputs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());String name="travel-test-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,0);TravelPlans.Factory oldFactory=TravelPlans.factory;TravelReminders.Port oldPort=TravelReminders.port;java.util.function.LongSupplier oldClock=TravelReminders.clock;AtomicLong now=new AtomicLong(Instant.parse("2026-10-23T12:00:00Z").toEpochMilli());List<TravelReminders.Request> queued=new CopyOnWriteArrayList<>(),cancelled=new CopyOnWriteArrayList<>();AtomicInteger shown=new AtomicInteger();AtomicBoolean fail=new AtomicBoolean();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof TravelActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{TravelPlans.factory=context->prefs;TravelReminders.clock=now::get;TravelReminders.port=new TravelReminders.Port(){public void schedule(Context context,TravelReminders.Request request){if(fail.get())throw new IllegalStateException("Scheduling is unavailable.");queued.add(request);}public void cancel(Context context,TravelReminders.Request request){if(request!=null)cancelled.add(request);}public void dismiss(Context context){}public boolean allowed(Context context){return true;}public void show(Context context,TravelPlan plan,TravelReminders.Request request){shown.incrementAndGet();}};
            launch();assertTrue(prefs.getAll().isEmpty());clickDescription("Home time zone");object("Search time zones").setText("Riyadh");clickDescription("Use time zone Asia/Riyadh");clickDescription("Target time zone");object("Search time zones").setText("London");capture("zones");clickDescription("Use time zone Europe/London");clickDescription("Departure date");capture("date");clickDescription("Departure 2026-10-27");capture("plan");
            clickDescription("Schedules & reminders");capture("schedules");clickDescription("Daylight reminders");assertTrue(device.wait(Until.hasObject(By.text("Reminder time")),5000));assertFalse(object("Daylight reminders").isChecked());clickDescription("Daylight reminders");clickDescription("Reminder time");assertTrue(device.wait(Until.hasObject(By.text("Daylight reminder time")),5000));object("Hour").setText("09");object("Minute").setText("15");if(device.hasObject(By.desc("AM")))clickDescription("AM");click("Use time");clickDescription("Remind for");clickDescription("5 days");capture("reminders");recreate("Reminder time");assertTrue(object("Daylight reminders").isChecked());assertTrue(device.hasObject(By.text("5 days")));capture("reminders-recreated");assertTrue(prefs.getAll().isEmpty());click("Done");assertTrue(device.wait(Until.hasObject(By.text("Pre-travel sleep schedule")),5000));click("Done");assertTrue(device.wait(Until.hasObject(By.text("Save travel settings")),5000));Activity first=activity;click("Save travel settings");destroyed(first);
            TravelPlans.Repository repo=new TravelPlans.Repository(prefs);TravelPlan saved=repo.load(now.get());assertEquals("Asia/Riyadh",saved.home);assertEquals("Europe/London",saved.destination);assertEquals(LocalDate.of(2026,10,27),saved.departure);assertEquals(555,saved.minute);assertEquals(5,saved.days);assertTrue(saved.reminders);TravelReminders.Request firstReminder=repo.pending();assertNotNull(firstReminder);assertEquals(Instant.parse("2026-10-27T09:15:00Z").toEpochMilli(),firstReminder.at);assertEquals(1,queued.size());assertEquals(0,shown.get());
            // The actual receiver engine consumes/delivers/rearms through fake outputs only.
            now.set(firstReminder.at);TravelReminders.receive(c,firstReminder);assertEquals(1,shown.get());assertEquals(firstReminder.at,repo.delivered());TravelReminders.Request next=repo.pending();assertEquals(Instant.parse("2026-10-28T09:15:00Z").toEpochMilli(),next.at);TravelReminders.receive(c,firstReminder);assertEquals(1,shown.get());now.set(Instant.parse("2026-10-23T12:00:00Z").toEpochMilli());TravelReminders.apply(c);assertEquals(next.at,repo.pending().at);
            launch();capture("reopened");clickDescription("Schedules & reminders");clickDescription("Daylight reminders");assertTrue(object("Daylight reminders").isChecked());assertTrue(device.hasObject(By.text("5 days")));capture("reminders-reopened");click("Done");click("Done");fail.set(true);try{TravelReminders.apply(c);fail("Scheduling failure must surface");}catch(IllegalStateException expected){}assertNull(repo.pending());assertTrue(repo.load(now.get()).reminders);recreate("Save travel settings");UiObject2 visibleError=object("Travel settings error");assertTrue("Reminder failure is visible above Save",visibleError.getVisibleBounds().height()>0);assertFalse(visibleError.getText().isEmpty());UiObject2 retry=device.wait(Until.findObject(By.text("Retry saved reminders")),3000);assertNotNull(retry);assertTrue(retry.getVisibleBounds().height()>0);capture("error");clickDescription("Schedules & reminders");clickDescription("Daylight reminders");clickDescription("Remind for");clickDescription("6 days");fail.set(false);click("Retry saved reminders");assertTrue(device.wait(Until.hasObject(By.text("Done")),5000));long deadline=SystemClock.elapsedRealtime()+5000;while(repo.pending()==null&&SystemClock.elapsedRealtime()<deadline)SystemClock.sleep(50);assertNotNull(repo.pending());assertTrue(device.wait(Until.hasObject(By.text("6 days")),5000));assertEquals(5,repo.load(now.get()).days);
            clickDescription("Daylight reminders");assertFalse(object("Daylight reminders").isChecked());capture("disabled");click("Done");click("Done");capture("disabled-main");Activity last=activity;click("Save travel settings");destroyed(last);assertFalse(repo.load(now.get()).reminders);assertNull(repo.pending());assertFalse(cancelled.isEmpty());TravelReminders.receive(c,next);assertEquals(1,shown.get());assertEquals(personal,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"travel-failure.png"));device.dumpWindowHierarchy(new File(folder,"travel-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{PlanOperations.drain(10000);long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();SystemClock.sleep(50);}assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);TravelPlans.factory=oldFactory;TravelReminders.port=oldPort;TravelReminders.clock=oldClock;if(owned.stream().allMatch(Activity::isDestroyed))c.deleteSharedPreferences(name);}}
    }
}
